CREATE TABLE prime_contracts (contract_id TEXT PRIMARY KEY, procurement_id TEXT NOT NULL, owner_id TEXT NOT NULL, contractor_id TEXT NOT NULL, contract_number TEXT NOT NULL UNIQUE, original_contract_cents INTEGER NOT NULL CHECK (original_contract_cents >= 0), approved_change_order_cents INTEGER NOT NULL DEFAULT 0 CHECK (approved_change_order_cents >= 0), draft_change_order_cents INTEGER NOT NULL DEFAULT 0 CHECK (draft_change_order_cents >= 0), executed_change_order_count INTEGER NOT NULL DEFAULT 0 CHECK (executed_change_order_count >= 0), status TEXT NOT NULL CHECK (status IN ('active','closed','pending')), effective_date TEXT NOT NULL, created_at TEXT NOT NULL);

CREATE TABLE pay_applications (application_id TEXT PRIMARY KEY, contract_id TEXT NOT NULL, application_number INTEGER NOT NULL CHECK (application_number > 0), period_start_date TEXT NOT NULL, period_end_date TEXT NOT NULL, submission_status TEXT NOT NULL CHECK (submission_status IN ('draft','submitted','under_review','approved','rejected')), retainage_work_bp INTEGER NOT NULL CHECK (retainage_work_bp BETWEEN 0 AND 10000), retainage_stored_materials_bp INTEGER NOT NULL CHECK (retainage_stored_materials_bp BETWEEN 0 AND 10000), contractor_submitted_total_percent_bp INTEGER CHECK (contractor_submitted_total_percent_bp BETWEEN 0 AND 10000), submitted_contract_sum_cents INTEGER CHECK (submitted_contract_sum_cents >= 0), total_earned_less_retainage_cents INTEGER CHECK (total_earned_less_retainage_cents >= 0), amount_paid_to_date_cents INTEGER CHECK (amount_paid_to_date_cents >= 0), current_payment_due_cents INTEGER CHECK (current_payment_due_cents >= 0), balance_to_finish_cents INTEGER CHECK (balance_to_finish_cents >= 0), submitted_at TEXT, FOREIGN KEY (contract_id) REFERENCES prime_contracts(contract_id), UNIQUE (contract_id, application_number));

CREATE TABLE sov_items (sov_item_id TEXT PRIMARY KEY, contract_id TEXT NOT NULL, item_no TEXT NOT NULL, cost_code TEXT NOT NULL, contractor_description TEXT NOT NULL, canonical_description TEXT NOT NULL, scheduled_value_cents INTEGER NOT NULL CHECK (scheduled_value_cents >= 0), source_type TEXT NOT NULL CHECK (source_type IN ('lump_sum','unit_price','allowance','change_order')), FOREIGN KEY (contract_id) REFERENCES prime_contracts(contract_id), UNIQUE (contract_id, item_no), UNIQUE (contract_id, cost_code));

CREATE TABLE pay_application_lines (application_line_id TEXT PRIMARY KEY, application_id TEXT NOT NULL, sov_item_id TEXT NOT NULL, source_line_number INTEGER NOT NULL, line_version INTEGER NOT NULL DEFAULT 1 CHECK (line_version > 0), previous_work_cents INTEGER NOT NULL DEFAULT 0 CHECK (previous_work_cents >= 0), current_work_cents INTEGER NOT NULL DEFAULT 0 CHECK (current_work_cents >= 0), stored_materials_cents INTEGER NOT NULL DEFAULT 0 CHECK (stored_materials_cents >= 0), contractor_percent_bp INTEGER CHECK (contractor_percent_bp BETWEEN 0 AND 10000), is_superseded INTEGER NOT NULL DEFAULT 0 CHECK (is_superseded IN (0,1)), superseded_by_line_id TEXT, audit_status TEXT NOT NULL CHECK (audit_status IN ('imported','audited','rejected')), source_system TEXT NOT NULL, reported_at TEXT NOT NULL, FOREIGN KEY (application_id) REFERENCES pay_applications(application_id), FOREIGN KEY (sov_item_id) REFERENCES sov_items(sov_item_id), FOREIGN KEY (superseded_by_line_id) REFERENCES pay_application_lines(application_line_id), UNIQUE (application_id, sov_item_id, source_line_number, line_version));

CREATE TABLE application_summary_entries (summary_entry_id TEXT PRIMARY KEY, application_id TEXT NOT NULL, summary_version INTEGER NOT NULL CHECK (summary_version > 0), metric_code TEXT NOT NULL CHECK (metric_code IN ('COMPLETED_WORK','STORED_MATERIALS','RETAINAGE_WORK','RETAINAGE_STORED','PRIOR_PAYMENTS','CURRENT_PAYMENT_DUE','BALANCE_TO_FINISH','CONTRACT_SUM_TO_DATE')), component_label TEXT NOT NULL, amount_cents INTEGER NOT NULL CHECK (amount_cents >= 0), percent_bp INTEGER CHECK (percent_bp BETWEEN 0 AND 10000), is_current INTEGER NOT NULL DEFAULT 0 CHECK (is_current IN (0,1)), submission_basis TEXT NOT NULL CHECK (submission_basis IN ('contractor','audited')), source_sheet TEXT NOT NULL CHECK (source_sheet IN ('Summary','Lump Sum','Unit Price','Stored Materials')), recorded_at TEXT NOT NULL, FOREIGN KEY (application_id) REFERENCES pay_applications(application_id), UNIQUE (application_id, summary_version, metric_code, component_label, submission_basis));